const NAMES_512: [Option<&'static CStr>; 19] = [
    Some(c"-ERESTARTSYS"), // 512
    Some(c"-ERESTARTNOINTR"), // 513
    Some(c"-ERESTARTNOHAND"), // 514
    Some(c"-ENOIOCTLCMD"), // 515
    Some(c"-ERESTART_RESTARTBLOCK"), // 516
    Some(c"-EPROBE_DEFER"), // 517
    Some(c"-EOPENSTALE"), // 518
    Some(c"-ENOPARAM"), // 519
    None, // 520
    Some(c"-EBADHANDLE"), // 521
    Some(c"-ENOTSYNC"), // 522
    Some(c"-EBADCOOKIE"), // 523
    Some(c"-ENOTSUPP"), // 524
    Some(c"-ETOOSMALL"), // 525
    Some(c"-ESERVERFAULT"), // 526
    Some(c"-EBADTYPE"), // 527
    Some(c"-EJUKEBOX"), // 528
    Some(c"-EIOCBQUEUED"), // 529
    Some(c"-ERECALLCONFLICT"), // 530
];

fn lookup(err: u32) -> Option<&'static CStr> {
    if let Some(&entry) = NAMES_0.get(err as usize) {
        return entry;
    }
    if err >= 512 {
        if let Some(&entry) = NAMES_512.get((err - 512) as usize) {
            return entry;
        }
    }
    None
}

kernel::kabi_export! {
    errname,
    license = "",
    namespace = "",
    contract = "subprogram ( formal_parameter base_type int byte_size(4) encoding(5) err ) -> pointer_type { const_type { base_type char byte_size(1) encoding(8) } }",
}

/// `errname(EIO)` -> `"EIO"`; `errname(-EIO)` -> `"-EIO"`; an unknown or
/// zero `err` -> a null pointer.
///
/// # Safety
/// None -- `err` is a plain integer, not a pointer.
#[no_mangle]
pub unsafe extern "C" fn errname(err: c_int) -> *const c_char {
    let name = lookup(err.unsigned_abs());
    match name {
        None => core::ptr::null(),
        // SAFETY: `p` points at a `'static` NUL-terminated string literal
        // beginning with `-`; offsetting by 1 stays within (and NUL-
        // terminated within) that same literal for every entry in the
        // tables above.
        Some(n) => {
            let p = n.as_ptr();
            if err > 0 {
                unsafe { p.add(1) }
            } else {
                p
            }
        }
    }
}
